// Follow-up Logic
const items = $input.all();
const today = new Date();
const followups = [];

for (const item of items) {
  const lead = item.json;
  const lastContact = new Date(lead.last_contact_date || today);
  const daysSinceContact = Math.floor((today - lastContact) / (1000 * 60 * 60 * 24));

  let action = null;
  let message = "";
  let channel = "email";

  // Regras de follow-up
  if (daysSinceContact === 3 && lead.stage === "proposta_enviada") {
    action = "reminder";
    message = `Olá ${lead.name}, lembrando sobre a proposta enviada. Tem alguma dúvida?`;
  } else if (daysSinceContact === 7 && lead.stage === "primeiro_contato") {
    action = "checkin";
    message = `Olá ${lead.name}, como está indo a avaliação da solução?`;
  } else if (daysSinceContact === 14 && lead.stage === "negociacao") {
    action = "urgency";
    message = `${lead.name}, temos uma promoção especial que acaba esta semana!`;
    channel = "whatsapp";
  } else if (daysSinceContact >= 30) {
    action = "reengagement";
    message = `Olá ${lead.name}, ainda tem interesse? Temos novidades!`;
  }

  if (action) {
    followups.push({
      json: {
        ...lead,
        followup_action: action,
        followup_message: message,
        followup_channel: channel,
        followup_scheduled: true,
        days_since_contact: daysSinceContact
      }
    });
  }
}

return followups;
